let REGISTRY=[];
function norm(s){s=(s||"").trim();if(REGISTRY.some(x=>x.code===s))return s;return map[s]||map[s.toLowerCase()]||(M[s]?s:(REGISTRY.some(x=>x.code===s.split("-")[0])?s.split("-")[0]:(M[s.split("-")[0]]?s.split("-")[0]:"en")));}
async function loadRegistry(){try{const r=await fetch("./locales/languages.json",{cache:"no-store"});if(r.ok){const j=await r.json();REGISTRY=(j.languages||[]).filter(x=>x.code==="en"||x.available!==false);const sel=document.getElementById("language-select");if(sel&&REGISTRY.length){sel.innerHTML='<option value="auto">🌐 Auto</option>'+REGISTRY.map(x=>'<option value="'+x.code+'">'+x.name+'</option>').join("");sel.setAttribute("aria-label","Choose language");}}}catch(e){console.warn("Language registry unavailable",e);}}

function preferred(){const ls=navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||"en"];for(const l of ls){const raw=(l||"").trim();if(REGISTRY.some(x=>x.code.toLowerCase()===raw.toLowerCase()))return REGISTRY.find(x=>x.code.toLowerCase()===raw.toLowerCase()).code;const base=raw.split("-")[0];if(REGISTRY.some(x=>x.code===base))return base;const n=norm(raw);if(M[n])return n;}return "en";}
